"""Orchestrator-initiated A2A cancel: dialogue updates and terminal task publish.

Cancel is split into three phases elsewhere in the stack:

1. **Signal** — ``RasaA2AAgentExecutor`` interrupts in-flight work
   (``tasks/cancel``).
2. **Apply dialogue** — tracker updates and ``pattern_cancel_flow``.
3. **Publish A2A** — ``A2AOutputChannel.publish_terminal_canceled`` closes the task.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Optional

import structlog

from rasa.core.a2a_server.a2a_output_channel import A2AOutputChannel
from rasa.dialogue_understanding.commands.cancel_flow_command import CancelFlowCommand
from rasa.dialogue_understanding.patterns.cancel import CancelPatternFlowStackFrame
from rasa.dialogue_understanding.stack.utils import get_active_pattern_frame
from rasa.shared.core.events import Event

if TYPE_CHECKING:
    from rasa.core.agent import Agent
    from rasa.shared.core.flows import FlowsList

structlogger = structlog.get_logger()


class OrchestratorCancelTurn:
    """Coordinates tracker cancel, cancel-pattern execution, and A2A task closure."""

    @staticmethod
    async def run(
        agent: "Agent",
        sender_id: str,
        output_channel: A2AOutputChannel,
        *,
        flows: Optional["FlowsList"] = None,
    ) -> None:
        """Run the full orchestrator-cancel turn (dialogue apply + terminal publish)."""
        if flows is None and agent.processor is not None:
            flows = await agent.processor.get_flows()

        if output_channel.cancel_turn_context is None:
            output_channel.begin_orchestrator_cancel_turn()

        if await OrchestratorCancelTurn.update_tracker_for_cancel(
            agent, sender_id, flows=flows
        ):
            await OrchestratorCancelTurn.run_cancel_pattern_flow(
                agent, sender_id, output_channel, flows=flows
            )

        await output_channel.publish_terminal_canceled(flows=flows)

    @staticmethod
    async def update_tracker_for_cancel(
        agent: "Agent",
        sender_id: str,
        *,
        flows: Optional["FlowsList"] = None,
    ) -> bool:
        """Push ``CancelPatternFlowStackFrame`` when a user flow is active.

        Returns:
            ``True`` if cancel events were applied, ``False`` if there was no active
            user flow to cancel.
        """
        processor = agent.processor
        if processor is None:
            return False

        if flows is None:
            flows = await processor.get_flows()

        async with agent.lock_store.lock(sender_id):
            tracker = await processor.get_tracker(sender_id)
            original_tracker = tracker.copy()
            command = CancelFlowCommand()
            events: list[Event] = command.run_command_on_tracker(
                tracker, flows, original_tracker
            )
            if not events:
                structlogger.debug(
                    "a2a_server.cancellation.skip_no_active_flow",
                    sender_id=sender_id,
                )
                return False

            for event in events:
                tracker.update(event)
            await processor.save_tracker(tracker)
            return True

    @staticmethod
    async def run_cancel_pattern_flow(
        agent: "Agent",
        sender_id: str,
        output_channel: A2AOutputChannel,
        *,
        flows: Optional["FlowsList"] = None,
    ) -> None:
        """Advance ``pattern_cancel_flow`` after a cancel frame was pushed."""
        processor = agent.processor
        if processor is None:
            return

        if flows is None:
            flows = await processor.get_flows()

        async with agent.lock_store.lock(sender_id):
            tracker = await processor.get_tracker(sender_id)
            cancel_frame = get_active_pattern_frame(
                tracker.stack, CancelPatternFlowStackFrame
            )
            if not isinstance(cancel_frame, CancelPatternFlowStackFrame):
                return

            cancellation_token = processor._active_cancellation_tokens.get(sender_id)
            await processor._run_prediction_loop(
                output_channel,
                tracker,
                cancellation_token,
                flows=flows,
            )
            await processor.save_tracker(tracker)
